import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"MCP: A Standard Way to Connect Agents with Tools","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/mcp.md","filePath":"learn/01-agent-basics/mcp.md","lastUpdated":1792595354000}'),s={name:"learn/01-agent-basics/mcp.md"};function i(r,t,c,l,d,p){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="mcp-a-standard-way-to-connect-agents-with-tools" tabindex="-1">MCP: A Standard Way to Connect Agents with Tools <a class="header-anchor" href="#mcp-a-standard-way-to-connect-agents-with-tools" aria-label="Permalink to &quot;MCP: A Standard Way to Connect Agents with Tools&quot;">​</a></h1><p>The Model Context Protocol (MCP) defines a common way for AI applications to connect to external context and capabilities. It addresses the integration problem where each model host and tool provider would otherwise need a custom connector. MCP is an integration protocol; it does not decide what an agent should do or whether an action is authorized.</p><h2 id="roles-and-capabilities" tabindex="-1">Roles and capabilities <a class="header-anchor" href="#roles-and-capabilities" aria-label="Permalink to &quot;Roles and capabilities&quot;">​</a></h2><p>An MCP <strong>host</strong> is the AI application. An MCP <strong>client</strong> in the host communicates with an MCP <strong>server</strong>, which may expose <strong>tools</strong> (operations the model may request), <strong>resources</strong> (data the client can read), and <strong>prompts</strong> (reusable templates). The host decides which servers and capabilities are available.</p><h2 id="typical-interaction" tabindex="-1">Typical interaction <a class="header-anchor" href="#typical-interaction" aria-label="Permalink to &quot;Typical interaction&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host connects to server → discovers tools/resources</span></span>
<span class="line"><span>Model requests a tool → host/client sends request</span></span>
<span class="line"><span>Server returns result → host provides it to model</span></span></code></pre></div><p>Local and remote servers have different operational and security considerations. Treat each server as an integration with a trust boundary: review what data it receives, what operations it can perform, and how credentials are supplied. Apply least privilege and validate inputs and outputs.</p><p>Tool output may contain prompt injection. Treat it as untrusted data, not instructions that override application policy. Enforce high-impact actions outside the model.</p><p>MCP is not a payment protocol or financial control plane. A payment-enabled tool still needs recipient and amount validation, budgets, protected signing authority, and safe retry and settlement handling.</p>`,9)])])}const m=e(s,[["render",i]]);export{u as __pageData,m as default};
